"""Aggregate accepted event deltas by stream with retry suppression."""

from rules import accepted


def totals(events):
    seen = set()
    result = {}
    for event in events:
        if not accepted(event):
            continue
        key = (event["stream"], event["id"])
        if key in seen:
            continue
        seen.add(key)
        stream = event["stream"]
        result[stream] = result.get(stream, 0) + event["delta"]
    return result
